const results = await Promise.allSettled([
  tools.exec_command({cmd:"Get-Content -LiteralPath docs/README.md", max_output_tokens:6500}),
  tools.exec_command({cmd:"git status --short --branch", max_output_tokens:2500}),
  tools.exec_command({cmd:"python -I scripts/ai_logging/cli.py status", max_output_tokens:6500})
]);
results.forEach((r,i)=>text({i,...(r.status==="fulfilled"?{result:r.value}:{error:String(r.reason)})}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"Get-Content -Encoding UTF8 -LiteralPath docs/README.md, docs/common/ai-logging.md", max_output_tokens:15000}),
