def _stable_read(path: str) -> bytes:
    for _ in range(3):
        before = os.path.getsize(path)
        with open(path, "rb") as fh:
            data = fh.read()
        if os.path.getsize(path) == before == len(data):
            return data
        time.sleep(0.2)
    raise OSError("unstable_file")


