def verify(ctx: Context, final: bool = False) -> dict:
    """읽기 전용 live 검사. 파일·상태·manifest를 바꾸지 않는다.

    - 사본 = 원본 앞부분의 마스킹 결과(바이트 동일), 민감정보·치환 목록 잔류 없음
