"""GROUP-001 로그 오탐 허용 범위와 개인정보 마스킹 회귀 검사."""
import json
import os
from pathlib import Path
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]
if ROOT.name == ".ai-logging":
    ROOT = ROOT.parent
sys.path.insert(0, str(ROOT / "scripts/ai_logging"))
from ailog.policy import Policy, load_allowlist


class LogReviewPolicyTests(unittest.TestCase):
    def setUp(self):
        allowlist = os.environ.get("AI_LOG_REVIEW_ALLOWLIST") or ROOT / "config/ai-logs-allowlist.json"
        self.policy = Policy([], load_allowlist(str(allowlist)))

    def test_kotlin_receiver_expressions_are_preserved(self):
        source = b"this@HttpGroupMembershipTests.executor\nthis@GroupRetryHttpTests.executor\n"
        self.assertEqual(self.policy.detect(source), [])
        self.assertEqual(self.policy.mask(source)[0], source)

    def test_reviewed_emails_do_not_allow_other_contacts(self):
        source = ("another-person" + "@" + "example.invalid").encode()
        self.assertIn("email", {h.rule for h in self.policy.detect(source)})

    def test_type_exception_does_not_allow_longer_secret(self):
        self.assertEqual(self.policy.detect(b"token: String"), [])
        value = b"String" + b"PrivateValue9"
        self.assertIn("keyword:token", {h.rule for h in self.policy.detect(b"token=" + value)})

    def test_wrapper_checksum_is_not_a_general_password_exception(self):
        lines = (ROOT / "gradle/wrapper/gradle-wrapper.properties").read_bytes().splitlines()
        assignment = next(line for line in lines if line.startswith(b"distributionSha256Sum="))
        self.assertEqual(self.policy.detect(assignment), [])
        digest = assignment.split(b"=", 1)[1]
        self.assertIn("keyword:password", {h.rule for h in self.policy.detect(b"password=" + digest)})

    def test_private_email_masking_preserves_record_order(self):
        contact = "private-person" + "@" + "mail.invalid"
        policy = Policy([{"kind":"literal", "value":contact}], self.policy.allow)
        source = (json.dumps({"order":1,"text":contact}) + "\r\n" + json.dumps({"order":2,"text":"unchanged"}) + "\r\n").encode()
        masked, _ = policy.mask(source)
        self.assertEqual(masked, source.replace(contact.encode(), b"****"))
        self.assertEqual([json.loads(line)["order"] for line in masked.splitlines()], [1,2])
        self.assertEqual(policy.residue(masked), 0)

    def test_new_opaque_url_value_still_requires_review(self):
        value = b"Qx7Ab9Cd2Ef8" + b"Gh3Jk6Lm1Np5" + b"Rs4Tu0Vw8Xy6"
        self.assertIn("random_string", {h.rule for h in self.policy.detect(b"https://public.invalid/view/" + value)})

    def test_approved_pdf_identifier_is_preserved_but_other_ids_are_held(self):
        identifier = b"832470d42097c20b28e60aa4a830b4502f1d5630"
        prefix = b"https://ydb.tech/docs/_/api/pdf?pdfRoot="
        source = prefix + identifier + b"%2Fen"
        self.assertEqual(self.policy.mask(source)[0], source)
        self.assertEqual(self.policy.detect(source), [])
        decoded = prefix + identifier + b"/en"
        self.assertEqual(self.policy.mask(decoded)[0], decoded)
        self.assertEqual(self.policy.detect(decoded), [])
        other = prefix + b"0" + identifier[1:] + b"%2Fen"
        self.assertIn("random_string", {h.rule for h in self.policy.detect(other)})


if __name__ == "__main__":
    unittest.main()
"""In-memory policy preview only; does not change active policy or logs."""
import json
import re
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts" / "ai_logging"))
from ailog import engine, snapshot
from ailog.common import default_context, git, utc_now, sha256
from ailog.discover import resolve_targets
from ailog.policy import Allowlist
from ailog.validation_cache import ValidationCache, scanner_digest

ctx = default_context()
list_id, candidates = engine.held_candidates(ctx)
classification = json.loads((Path(__file__).parent / "classification.json").read_text(encoding="utf-8"))
assert list_id == classification["list_id"]
by_no = {g["no"]: g for g in candidates}
allow = json.loads(Path(ctx.allowlist_path).read_bytes())
approved_candidates = []
masked_candidates = []
for row in classification["candidates"]:
    g = by_no[row["no"]]
    if row["keyword_source_evidence"] or row["library_symbol_evidence"] or row["known_tool_path_suffix"]:
        section = allow["keywords"]["value_patterns"] if g["rule"].startswith("keyword:") else allow["random_strings"]["patterns"]
        reason = "소스 표현식" if row["keyword_source_evidence"] else ("로컬 의존성 JAR의 클래스명·경로" if row["library_symbol_evidence"] else "원본·스냅샷의 도구 결과 파일 경로")
        section.append({"pattern": re.escape(g["value"].decode("utf-8")),
                        "reason": f"2026-11-06 조사: {reason}와 대조한 정확한 값만 허용 (승인 전 미적용 초안)"})
        approved_candidates.append(g["no"])
    else:
        masked_candidates.append(g["no"])
preview = engine.build_policy(ctx)
preview.allow = Allowlist(allow)
preview.literal_res = [re.compile(re.escape(by_no[n]["value"]), re.IGNORECASE) for n in masked_candidates] + preview.literal_res
preview.mask_digest = sha256(("preview:" + preview.mask_digest + ":" + ":".join(sha256(by_no[n]["value"]) for n in masked_candidates)).encode())
namespace = sha256(preview.version.encode() + preview.mask_digest.encode() + preview.allow.raw + scanner_digest().encode())
preview.cache = ValidationCache(ctx.p("verification-cache"), namespace)
issues = []
for s in resolve_targets(ctx, engine.load_state(ctx)).sessions:
    print(f"Preview content: {s.key}", flush=True)
    for f in s.files:
        data = engine.read_full(f)
        masked = preview.mask(data)[0]
        issues.extend(dict(x, session=s.key) for x in engine.check_masked(f.rel, data, masked, preview))
print("Preview committed snapshots", flush=True)
leaks = snapshot.scan_tree_secrets(ctx, "master", policy=preview)
report = {"time": utc_now(), "list_id": list_id, "active_policy_changed": False,
          "allow_exact_numbers": approved_candidates, "mask_numbers": masked_candidates,
          "original_content_preview_rules": dict(Counter(x["rule"] for x in issues)),
          "master_preview_rules": dict(Counter(x["rule"] for x in leaks)),
          "master": git(ctx.root, "rev-parse", "master").strip(),
          "notes": ["현재 후보 목록만을 대상으로 하는 비적용 검증", "원본 불변성·메타데이터 보류는 별도이며 해소되지 않음"]}
(Path(__file__).parent / "policy-preview.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
print(json.dumps(report, ensure_ascii=False))
"""AI 턴 중에 요청된 Git 작업의 예약·실행.

AI 턴이 진행 중일 때는 Git 변경을 막는다. 대신 작업을 .ai-logging/tasks.jsonl에 예약하고,
모든 세션이 idle로 확인되는 Stop 시점(또는 사용자의 `tasks run`)에 순서대로 실행한다.

- 기록은 추가 전용 이벤트(reserved / done / failed / cancelled / retry)다.
- 실행 조건: 모든 세션 idle, 스테이징된 변경 없음, 진행 중인 Git 작업 없음,
  예약 때와 같은 브랜치, HEAD가 예약 때 값(또는 바로 앞 예약 작업이 만든 값)과 같음.
- 실패한 작업이 있으면 뒤 작업은 실행하지 않는다(사용자가 retry 또는 cancel).
- 자동 stash·강제 checkout/reset·작업 폴더 정리는 하지 않는다. 커밋은 임시 index + CAS로 만든다.
"""
from __future__ import annotations

import json
import os
import uuid

from .common import Context, GitError, LockTimeout, append_jsonl, utc_now
from . import config, gitops, rules

KINDS = ("commit", "squash", "stage-log", "push-develop", "resume", "merge-feature")


def _events(ctx: Context) -> list[dict]:
    out = []
    try:
        with open(ctx.tasks_path, "rb") as f:
            for raw in f:
                try:
                    o = json.loads(raw)
                except ValueError:
                    continue
                if isinstance(o, dict):
                    out.append(o)
    except FileNotFoundError:
        pass
    return out


def listing(ctx: Context) -> list[dict]:
    """예약 작업과 현재 상태(pending/done/failed/cancelled) — 예약 순서."""
    tasks: dict[str, dict] = {}
    order = []
    for e in _events(ctx):
        tid = e.get("id")
        if e.get("event") == "reserved":
            tasks[tid] = dict(e, status="pending")
            order.append(tid)
        elif tid in tasks:
            ev = e.get("event")
            if ev == "done":
                tasks[tid].update(status="done", result=e.get("result"), finished=e.get("time"))
            elif ev == "failed":
                tasks[tid].update(status="failed", reason=e.get("reason"), finished=e.get("time"))
            elif ev == "cancelled":
                tasks[tid].update(status="cancelled")
            elif ev == "retry":
                tasks[tid].update(status="pending", reason=None)
    return [tasks[t] for t in order]


def _check_args(kind: str, args: dict) -> str | None:
    if kind not in KINDS:
        return "unknown_kind"
    msg = args.get("message")
    if kind in ("commit", "squash"):
        if not isinstance(msg, str) or rules.check_message(msg):
            return "message_format"
    if kind == "commit":
        paths = args.get("paths")
        if not paths or not all(isinstance(p, str) and p for p in paths):
            return "paths_required"
        for p in paths:
            n = p.replace("\\", "/").strip("/")
            if n in ("", ".") or n.startswith(("ai-logs", ".ai-logging", "..")) or os.path.isabs(p):
                return "path_not_allowed"
    if kind == "squash" and not args.get("onto"):
        return "onto_required"
    if kind == "stage-log" and not rules.TASK_ID_RE.match(args.get("task") or ""):
        return "task_id_format"
    if kind in ("push-develop", "resume", "merge-feature") and not args.get("feature"):
        return "feature_required"
    return None


def _task_of(kind: str, args: dict) -> str | None:
    if kind in ("commit", "squash"):
        return rules.task_from_title(args.get("message") or "")
    if kind == "stage-log":
        return args.get("task")
    return None


def reserve(ctx: Context, kind: str, args: dict, by: str | None = None) -> dict:
    bad = _check_args(kind, args)
    if bad:
        return {"ok": False, "reason": bad}
    if kind in ("commit", "squash", "stage-log"):
        mm = config.check_branch_task(ctx, _task_of(kind, args), gitops.current_branch(ctx.root))
        if mm:
            return {"ok": False, "reason": "task_branch_mismatch", "detail": mm.split(":", 1)[1]}
    if kind == "squash":
        onto = gitops.rev(ctx.root, args["onto"])
        if not onto:
            return {"ok": False, "reason": "onto_not_found"}
        args = dict(args, onto=onto)
    pend = [t for t in listing(ctx) if t["status"] in ("pending", "failed")]
    row = {
        "event": "reserved",
        "id": uuid.uuid4().hex[:12],
        "kind": kind,
        "args": args,
        "branch": gitops.current_branch(ctx.root),
        "head": gitops.rev(ctx.root, "HEAD"),
        "after": pend[-1]["id"] if pend else None,
        "by": by,
        "time": utc_now(),
    }
    append_jsonl(ctx.tasks_path, row)
    return {"ok": True, "id": row["id"], "kind": kind, "after": row["after"]}


def _mark(ctx: Context, tid: str, event: str, **kw) -> None:
    append_jsonl(ctx.tasks_path, dict({"event": event, "id": tid, "time": utc_now()}, **kw))


def cancel(ctx: Context, tid: str) -> dict:
    t = next((x for x in listing(ctx) if x["id"] == tid), None)
    if not t or t["status"] not in ("pending", "failed"):
        return {"ok": False, "reason": "not_pending"}
    _mark(ctx, tid, "cancelled")
    return {"ok": True}


def retry(ctx: Context, tid: str) -> dict:
    t = next((x for x in listing(ctx) if x["id"] == tid), None)

