"""수집(sync)·검증(verify)·상태(status)·색인(index)·설치(install)·hook 진입점."""
from __future__ import annotations

import glob
import json
import os
import re
import sys
import time
import traceback

from .common import (
    LIVE_REL,
    SCHEMA_VERSION,
    SNAPSHOTS_REL,
    Context,
    GitError,
    LockTimeout,
    append_jsonl,
    atomic_write,
    dumps_json,
    ensure_dir,
    file_lock,
    git,
    is_within,
    read_json,
    read_json_ro,
    sha256,
    utc_now,
    write_json,
)
from .discover import Session, SessionFile, Targets, resolve_targets
from .policy import Policy, load_allowlist, load_mask_entries, shape

# hook 이벤트 중 동기화를 실행하는 것. Codex SessionEnd는 제한 시간(최대 3초) 때문에 기록만 한다.
SYNC_EVENTS = {
    "claude": {"SessionStart", "Stop", "SessionEnd"},
    "codex": {"SessionStart", "Stop"},
}
MAX_REPORTED_HOLDS = 200


# --------------------------------------------------------------------- state
def _merge_manifest_knowledge(ctx: Context, files_state: dict) -> int:
    """live·스냅샷 manifest에 기록된 원본 길이·해시를 상태에 보충한다(읽기 전용).

    상태 파일이 손상·분실·과거본으로 돌아가도 원본 앞부분 불변성(재작성·절단) 검사를 잃지 않기 위해서다.
    더 긴(더 최근) 기록만 반영하고, 이렇게 보충한 항목은 증분 검증에 쓰지 않는다(policy=None).
    """
    merged = 0
    paths = glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json"))
    paths += glob.glob(os.path.join(ctx.snapshots_dir, "*", "*", "*", "*", "manifest.json"))
    for mpath in paths:
        m, status = read_json_ro(mpath)
        if status != "ok" or not isinstance(m, dict):
            continue
        live = m.get("kind") == "live"
        for e in m.get("files", []):
            if e.get("original_missing") or not isinstance(e.get("original_bytes"), int):
                continue
            fkey = f"{m.get('tool')}/{m.get('session_id')}/{e.get('path')}"
            cur = files_state.get(fkey)
            if cur is None or cur.get("original_bytes", -1) < e["original_bytes"]:
                files_state[fkey] = {
                    "original_bytes": e["original_bytes"],
                    "original_sha256": e.get("original_sha256"),
                    "copy_sha256": e.get("copy_sha256") if live else None,
                    "policy": None,
                    "mask_digest": None,
                    "from": "live_manifest" if live else "snapshot_manifest",
                }
                merged += 1
    return merged


def load_state(ctx: Context) -> dict:
    """상태 읽기(파일을 바꾸지 않음). 손상·분실 시 빈 상태로 초기화하지 않는다.

    순서: state.json → state.json.prev → manifest 기록 보충. 결과의 "_load"는 저장하지 않는 진단 정보다.
    """
    st, status = read_json_ro(ctx.state_path)
    load = {"state_file": status}
    if status != "ok" or not isinstance(st, dict):
        if status == "ok":
            load["state_file"] = "corrupt"
        prev, pst = read_json_ro(ctx.state_prev_path)
        if load["state_file"] == "corrupt" and pst == "ok" and isinstance(prev, dict):
            st, load["recovered_from"] = prev, "state.json.prev"
        else:
            st = {}
            if load["state_file"] == "corrupt":
                load["recovered_from"] = "manifests"
    st.setdefault("schema", SCHEMA_VERSION)
    load["manifest_entries_merged"] = _merge_manifest_knowledge(ctx, st.setdefault("files", {}))
    st["_load"] = load
    return st


def save_state(ctx: Context, state: dict) -> None:
    """상태 저장: 직전 정상본을 .prev로 남기고, 손상본은 지우지 않고 복사해 둔다."""
    data = {k: v for k, v in state.items() if k != "_load"}
    cur, status = read_json_ro(ctx.state_path)
    if status == "ok" and isinstance(cur, dict):
        atomic_write(ctx.state_prev_path, dumps_json(cur))
    elif status == "corrupt":
        try:
            with open(ctx.state_path, "rb") as f:
                atomic_write(f"{ctx.state_path}.corrupt-{int(time.time())}", f.read())
        except OSError:
            pass
    write_json(ctx.state_path, data)


def build_policy(ctx: Context) -> Policy:
    return Policy(load_mask_entries(ctx.mask_path), load_allowlist(ctx.allowlist_path),
                  cache_dir=ctx.p("verification-cache"))


# ------------------------------------------------------------------- reading
def _stable_read(path: str) -> bytes:
    for _ in range(3):
        before = os.path.getsize(path)
        with open(path, "rb") as fh:
            data = fh.read()
        if os.path.getsize(path) == before == len(data):
            return data
        time.sleep(0.2)
    raise OSError("unstable_file")


def read_complete(f: SessionFile) -> bytes:
    """live 수집용: 완결된 부분만. JSONL은 마지막 개행까지(작성 중인 줄은 다음 수집으로 미룸)."""
    if f.rel.endswith(".jsonl"):
        with open(f.path, "rb") as fh:
            data = fh.read()
        cut = data.rfind(b"\n")
        return data[: cut + 1] if cut >= 0 else b""
    return _stable_read(f.path)


def read_full(f: SessionFile) -> bytes:
    """최종 검사·스냅샷용: 실제 파일 끝(EOF)까지."""
    return _stable_read(f.path)


def _session_dir(ctx: Context, tool: str, sid: str) -> str:
    return os.path.join(ctx.live_dir, tool, sid)


def _copy_path(ctx: Context, s_tool: str, sid: str, rel: str) -> str:
    return os.path.join(_session_dir(ctx, s_tool, sid), "files", *rel.split("/"))


def _read_bytes(path: str):
    try:
        with open(path, "rb") as f:
            return f.read()
    except FileNotFoundError:
        return None


def jsonl_stats(data: bytes):
    """줄 수, 첫·마지막 최상위 timestamp(파일 순서 기준), 파싱 실패 줄 번호."""
    first = last = None
    bad = []
    lines = data.splitlines()
    for i, line in enumerate(lines, 1):
        try:
            o = json.loads(line)
        except ValueError:
            bad.append(i)
            continue
        ts = o.get("timestamp") if isinstance(o, dict) else None
        if isinstance(ts, str):
            first = first or ts
            last = ts
    return len(lines), first, last, bad


def _problem(rule, file=None, line=None, detail=""):
    p = {"rule": rule}
    if file is not None:
        p["file"] = file
    if line is not None:
        p["line"] = line
    if detail:
        p["detail"] = detail
    return p


def check_masked(rel: str, data: bytes, masked: bytes, policy: Policy, scan_from: int = 0,
                 old_lines: int = 0) -> list[dict]:
    """마스킹 결과 검사: 줄 수 유지, JSON 유효성 유지, 바이너리, 민감정보 후보, 치환 목록 잔류."""
    problems = []
    if masked.count(b"\n") != data.count(b"\n"):
        problems.append(_problem("mask_changed_line_count", rel))
    if rel.endswith(".jsonl"):
        for i, (o_line, m_line) in enumerate(zip(data.splitlines(), masked.splitlines()), 1):
            try:
                json.loads(o_line)
            except ValueError:
                continue  # 원본 자체가 JSON이 아닌 줄은 그대로 보존(검증 보고에만 표시)
            try:
                json.loads(m_line)
            except ValueError:
                problems.append(_problem("mask_broke_json", rel, i))
    else:
        try:
            data.decode("utf-8")
        except UnicodeDecodeError:
            if sha256(data) not in policy.allow.image_hashes:
                problems.append(_problem("binary_attachment", rel, detail=f"sha256={sha256(data)}"))
    for h in policy.detect(masked[scan_from:]):
        problems.append(_problem(h.rule, rel, h.line + old_lines, h.detail))
    if policy.residue(masked):
        problems.append(_problem("mask_residue", rel))
    return problems


# ------------------------------------------------------------------------ sync
def _process_session(ctx: Context, s: Session, policy: Policy, state: dict) -> dict:
    files_state = state.setdefault("files", {})
    sess_dir = _session_dir(ctx, s.tool, s.session_id)
    manifest_path = os.path.join(sess_dir, "manifest.json")
    old_manifest, mstatus = read_json_ro(manifest_path)
    problems, prepared = [], []
    if mstatus == "corrupt":
        # 손상 manifest는 덮어쓰지 않는다. 'repair' 명령으로 확인 후 복구한다.
        problems.append(_problem("live_manifest_unreadable"))
        old_manifest = None

    for f in s.files:
        fkey = f"{s.key}/{f.rel}"
        try:
            data = read_complete(f)
        except OSError as e:
            problems.append(_problem("original_unreadable", f.rel, detail=type(e).__name__))
            continue
        prev = files_state.get(fkey)
        if prev and isinstance(prev.get("original_bytes"), int):
            if len(data) < prev["original_bytes"]:
                problems.append(_problem("original_truncated", f.rel))
                continue
            if sha256(data[: prev["original_bytes"]]) != prev.get("original_sha256"):
                problems.append(_problem("original_rewritten", f.rel))
                continue
        masked, counts = policy.mask(data)
        # 같은 정책으로 이미 검증한 앞부분은 다시 검사하지 않는다(완결된 줄 단위인 JSONL만).
        # 그 밖의 부속 파일은 경계에 걸친 값을 놓치지 않도록 매번 전체를 검사한다.
        scan_from, old_lines = 0, 0
        if f.rel.endswith(".jsonl") and prev:
            old_copy = _read_bytes(_copy_path(ctx, s.tool, s.session_id, f.rel))
            if (
                old_copy is not None
                and prev.get("policy") == policy.version
                and prev.get("mask_digest") == policy.mask_digest
                and sha256(old_copy) == prev.get("copy_sha256")
                and (not old_copy or old_copy.endswith(b"\n"))
                and masked.startswith(old_copy)
            ):
                scan_from, old_lines = len(old_copy), old_copy.count(b"\n")
        problems.extend(check_masked(f.rel, data, masked, policy, scan_from, old_lines))
        prepared.append((f, fkey, data, masked, counts))

    summary = {"key": s.key, "tool": s.tool, "session_id": s.session_id}
    if problems:
        published = sum((files_state.get(f"{s.key}/{f.rel}") or {}).get("original_bytes", 0) for f in s.files)
        current = sum(len(d) for _, _, d, _, _ in prepared)
        summary.update(status="hold", pending_bytes=max(0, current - published), problems=len(problems))
        return {"summary": summary, "holds": [dict(p, session=s.key) for p in problems]}

    entries, changed = [], False
    main_stats = None
    for f, fkey, data, masked, counts in prepared:
        cpath = _copy_path(ctx, s.tool, s.session_id, f.rel)
        if _read_bytes(cpath) != masked:
            atomic_write(cpath, masked)
            changed = True
        entry = {
            "path": f.rel,
            "role": f.role,
            "original_bytes": len(data),
            "original_sha256": sha256(data),
            "copy_bytes": len(masked),
            "copy_sha256": sha256(masked),
            "masked": dict(sorted(counts.items())),
        }
        if f.rel.endswith(".jsonl"):
            n, first, last, bad = jsonl_stats(data)
            entry["lines"] = n
            if bad:
                entry["non_json_lines"] = bad[:50]
            if f.role == "main":
                main_stats = (n, first, last)
        entries.append(entry)
        files_state[fkey] = {
            "original_bytes": len(data),
            "original_sha256": entry["original_sha256"],
            "copy_sha256": entry["copy_sha256"],
            "policy": policy.version,
            "mask_digest": policy.mask_digest,
        }
    # 원본에서 사라진 부속 파일은 사본을 지우지 않고 표시만 한다.
    current_paths = {e["path"] for e in entries}
    for old in (old_manifest or {}).get("files", []):
        if old["path"] not in current_paths:
            entries.append(dict(old, original_missing=True))
    entries.sort(key=lambda e: (e["role"] != "main", e["path"]))
    n, first, last = main_stats or (0, None, None)
    manifest = {
        "schema": SCHEMA_VERSION,
        "kind": "live",
        "tool": s.tool,
        "session_id": s.session_id,
        "policy_version": policy.version,
        "time_basis": "UTC - 도구가 기록한 ISO 8601 timestamp 값을 그대로 사용",
        "order_basis": "파일 안의 줄 순서 (타임스탬프로 재정렬하지 않음)",
        "first_timestamp": first,
        "last_timestamp": last,
        "main_lines": n,
        "original_bytes_total": sum(e["original_bytes"] for e in entries if not e.get("original_missing")),
        "files": entries,
    }
    if _read_bytes(manifest_path) != dumps_json(manifest):
        write_json(manifest_path, manifest)
        changed = True
    summary.update(
        status="updated" if changed else "unchanged",
        lines=n,
        first_timestamp=first,
        last_timestamp=last,
        original_bytes=manifest["original_bytes_total"],
        files=len(entries),
    )
    return {"summary": summary, "holds": []}


def sync(ctx: Context, lock_timeout: float = 60.0) -> dict:
    ensure_dir(ctx.state_dir)
    with file_lock(ctx.lock_path, timeout=lock_timeout):
        state = load_state(ctx)
        policy = build_policy(ctx)
        targets = resolve_targets(ctx, state)
        report = {
            "time": utc_now(),
            "policy_version": policy.version,
            "mask_list_present": os.path.exists(ctx.mask_path),
            "state_load": state.get("_load"),
            "sessions": [],
            "holds": [],
            "holds_total": 0,
            "errors": [],
            "unresolved_codex_files": targets.unresolved,
            "missing_sessions": targets.missing,
        }
        if not report["mask_list_present"]:
            # 치환 목록 없이 사본을 만들면 계정 식별자가 그대로 남는다. 아무것도 쓰지 않는다.
            report["errors"].append({"error": "mask_list_missing", "where": "install 명령을 먼저 실행"})
            report["result"] = "error"
            write_json(ctx.last_sync_path, report)
            return report
        known = state.setdefault("known_sessions", {})
        for s in targets.sessions:
            info = known.setdefault(s.key, {"first_seen": utc_now()})
            info["main"] = s.main_path
            try:
                res = _process_session(ctx, s, policy, state)
            except Exception as e:  # 세션 하나의 실패가 다른 세션 수집을 막지 않게 한다.
                report["errors"].append({"session": s.key, "error": type(e).__name__, "where": _where(e)})
                continue
            report["sessions"].append(res["summary"])
            report["holds_total"] += len(res["holds"])
            room = MAX_REPORTED_HOLDS - len(report["holds"])
            report["holds"].extend(res["holds"][: max(0, room)])
        for key in targets.missing:
            known.setdefault(key, {"first_seen": utc_now()})
            report["sessions"].append({"key": key, "status": "original_missing"})
        report["result"] = "error" if report["errors"] else ("hold" if report["holds_total"] else "ok")
        state["last_sync"] = report["time"]
        save_state(ctx, state)
        write_json(ctx.last_sync_path, report)
        return report


# ---------------------------------------------------------------------- verify
def _list_files(base: str) -> set[str]:
    out = set()
    for dirpath, _, filenames in os.walk(base):
        for fn in filenames:
            out.add(os.path.relpath(os.path.join(dirpath, fn), base).replace(os.sep, "/"))
    return out


def tail_status(f: SessionFile, data_full: bytes, collected: int) -> str | None:
    """수집 범위 뒤에 남은 원본 꼬리의 종류. None이면 남은 것 없음."""
    extra = data_full[collected:]
    if not extra:
        return None
    if f.rel.endswith(".jsonl") and b"\n" not in extra:
        return "incomplete_tail"
    return "behind_original"


def verify(ctx: Context, final: bool = False) -> dict:
    """읽기 전용 live 검사. 파일·상태·manifest를 바꾸지 않는다.

    - 사본 = 원본 앞부분의 마스킹 결과(바이트 동일), 민감정보·치환 목록 잔류 없음
    - manifest에 없는 파일(a), 원본 꼬리(b), 대상 세션 합집합의 누락·원본 부재(c), manifest 손상(e)
    final=True면 원본보다 뒤처진 사본·미완성 꼬리·정책 변경도 실패로 본다.
    """
    policy = build_policy(ctx)
    state = load_state(ctx)
    targets = resolve_targets(ctx, state)
    by_key = {s.key: s for s in targets.sessions}
    failures, warnings = [], []
    soft = failures if final else warnings
    manifests = {}
    if os.path.isdir(ctx.live_dir):
        for tool in sorted(os.listdir(ctx.live_dir)):
            tdir = os.path.join(ctx.live_dir, tool)
            if not os.path.isdir(tdir):
                continue
            for sid in sorted(os.listdir(tdir)):
                sdir = os.path.join(tdir, sid)
                if not os.path.isdir(sdir):
                    continue
                key = f"{tool}/{sid}"
                m, status = read_json_ro(os.path.join(sdir, "manifest.json"))
                if status == "missing":
                    failures.append(dict(_problem("manifest_missing"), session=key))
                elif status != "ok" or not isinstance(m, dict) or "files" not in m:
                    failures.append(dict(_problem("manifest_unreadable"), session=key))
                else:
                    manifests[key] = m
    if not os.path.exists(ctx.mask_path):
        failures.append(_problem("mask_list_missing"))
    for key in targets.missing:
        soft.append(dict(_problem("original_missing"), session=key))
    bad_manifest = {f.get("session") for f in failures}
    for key in sorted(set(by_key) - set(manifests) - bad_manifest):
        failures.append(dict(_problem("not_collected"), session=key))
    if targets.unresolved:
        warnings.append(_problem("unresolved_codex_files", detail=f"count={targets.unresolved}"))
    checked = 0
    for key, m in manifests.items():
        s = by_key.get(key)
        if m.get("policy_version") != policy.version:
            soft.append(dict(_problem("policy_version_changed"), session=key))
        orig_files = {f.rel: f for f in (s.files if s else [])}
        listed = {e["path"] for e in m["files"]}
        for rel in sorted(set(orig_files) - listed):
            soft.append(dict(_problem("attachment_not_collected", rel), session=key))
        actual = _list_files(os.path.join(ctx.live_dir, *key.split("/"), "files"))
        for rel in sorted(actual - listed):
            failures.append(dict(_problem("unlisted_file", rel), session=key))
        for e in m["files"]:
            checked += 1
            copy = _read_bytes(_copy_path(ctx, m["tool"], m["session_id"], e["path"]))
            if copy is None or sha256(copy) != e["copy_sha256"]:
                failures.append(dict(_problem("copy_hash_mismatch", e["path"]), session=key))
                continue
            f = orig_files.get(e["path"])
            if f is None or e.get("original_missing"):
                soft.append(dict(_problem("original_missing", e["path"]), session=key))
                continue
            try:
                data = read_full(f)
            except OSError:
                failures.append(dict(_problem("original_unreadable", e["path"]), session=key))
                continue
            if len(data) < e["original_bytes"]:
                failures.append(dict(_problem("original_truncated", e["path"]), session=key))
                continue
            prefix = data[: e["original_bytes"]]
            if sha256(prefix) != e["original_sha256"]:
                failures.append(dict(_problem("original_rewritten", e["path"]), session=key))
                continue
            if policy.mask(prefix)[0] != copy:
                failures.append(dict(_problem("copy_not_masked_original", e["path"]), session=key))
            for h in policy.detect(copy):
                failures.append(dict(_problem(h.rule, e["path"], h.line, h.detail), session=key))
            if policy.residue(copy):
                failures.append(dict(_problem("mask_residue", e["path"]), session=key))
            tail = tail_status(f, data, e["original_bytes"])
            if tail:
                soft.append(dict(_problem(tail, e["path"], detail=f"bytes={len(data) - e['original_bytes']}"),
                                 session=key))
    return {
        "time": utc_now(),
        "final": final,
        "sessions_discovered": len(by_key),
        "sessions_missing": len(targets.missing),
        "sessions_collected": len(manifests),
        "files_checked": checked,
        "failures": failures,
        "warnings": warnings,
        "ok": not failures,
    }


# ----------------------------------------------------------------------- index
def build_index(ctx: Context, write: bool = True) -> list[dict]:
    rows = []
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m = read_json(mpath, None)
        if not m:
            continue
        rows.append(
            {
                "tool": m["tool"],
                "session_id": m["session_id"],
                "first_timestamp": m.get("first_timestamp"),
                "last_timestamp": m.get("last_timestamp"),
                "main_lines": m.get("main_lines"),
                "files": len(m.get("files", [])),
                "path": os.path.relpath(os.path.dirname(mpath), ctx.root).replace(os.sep, "/"),
            }
        )
    rows.sort(key=lambda r: (r["first_timestamp"] or "9999", r["tool"], r["session_id"]))
    if write:
        write_json(ctx.index_path, {"time": utc_now(), "time_basis": "UTC", "sessions": rows})
    return rows


# --------------------------------------------------------------------- install
_EMAIL_TEXT_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}")


def extract_mask_values(ctx: Context, sessions: list[Session]) -> list[dict]:
    """원본에서 자동으로 기록되는 식별자를 찾아 치환 목록 후보를 만든다(값은 출력하지 않는다)."""

"""공통 커밋 메시지 형식과 로그 전용 변경 판정. Git hook과 자동화 명령이 같은 검사기를 쓴다."""
from __future__ import annotations

import json
import re

from .common import LIVE_REL, SNAPSHOTS_REL, sha256

TITLE_RE = re.compile(r"^\[(?P<svc>[A-Z][A-Z0-9]*)-(?P<task>[A-Z0-9]+(?:-[A-Z0-9]+)*)\] \S.*$")
TRAILER_RE = re.compile(r"^[A-Za-z][A-Za-z0-9-]*: \S.*$")
CHERRY_RE = re.compile(r"^\(cherry picked from commit [0-9a-f]{7,64}\)$")
TASK_ID_RE = re.compile(r"^[A-Z][A-Z0-9]*-[A-Z0-9]+(?:-[A-Z0-9]+)*$")
SNAP_DIR_RE = re.compile(
    r"^" + re.escape(SNAPSHOTS_REL) + r"/(?P<tool>claude|codex)/(?P<sid>[^/]+)/(?P<policy>[0-9a-f]{12})/"
    r"(?P<snap>L\d{20}-[0-9a-f]{16})/(?P<rest>.+)$"
)
FORBIDDEN_PREFIXES = (LIVE_REL + "/", ".ai-logging/")


def check_message(text: str) -> list[str]:
    """`[작업ID] 제목` + 빈 줄 + 두 칸 들여쓴 작업 내용. 위반 사유 목록(빈 목록이면 통과).

    작업 ID는 `영문대문자로 시작하는 단어-단어...`(예: SETUP-001, AI-LOG-001). 브랜치와의 일치는 config.check_branch_task.
    """
    lines = [ln for ln in text.replace("\r\n", "\n").split("\n") if not ln.startswith("#")]
    while lines and not lines[-1].strip():
        lines.pop()
    if not lines or not TITLE_RE.match(lines[0]):
        return ["title_format"]
    if len(lines) < 3 or lines[1] != "":
        return ["body_missing"]
    body = [ln for ln in lines[2:] if ln.strip()]
    if not any(ln.startswith("  ") and ln.strip() for ln in body):
        return ["body_indent"]
    for ln in body:
        if not (ln.startswith("  ") or TRAILER_RE.match(ln) or CHERRY_RE.match(ln)):
            return ["body_indent"]
    return []


def task_from_title(text: str):
    m = TITLE_RE.match(text.split("\n", 1)[0])
    return f"{m.group('svc')}-{m.group('task')}" if m else None


def is_log_path(path: str) -> bool:
    return path.startswith(SNAPSHOTS_REL + "/")


def snapshot_groups(paths) -> tuple[dict[str, list[str]], list[str]]:
    """스냅샷 경로를 스냅샷 폴더별로 묶는다. (그룹, 형식이 맞지 않는 경로)."""
    groups: dict[str, list[str]] = {}
    bad = []
    for p in paths:
        m = SNAP_DIR_RE.match(p)
        if not m:
            bad.append(p)
            continue
        base = p[: len(p) - len(m.group("rest"))]
        groups.setdefault(base, []).append(m.group("rest"))
    return groups, bad


def check_snapshot_group(base: str, rests: list[str], blob) -> list[str]:
    """스냅샷 폴더 하나의 완전성: manifest와 파일 목록·blob sha256 일치, ID 재계산 일치.

    blob(path) -> bytes | None 는 검사 대상(index 또는 커밋)의 실제 내용을 돌려준다.
    """
    from .snapshot import snapshot_id, snapshot_sha256  # 순환 import 방지

    if "manifest.json" not in rests:
        return ["snapshot_manifest_missing"]
    raw = blob(base + "manifest.json")
    try:
        m = json.loads(raw.decode("utf-8"))
    except (AttributeError, ValueError, UnicodeDecodeError):
        return ["snapshot_manifest_unreadable"]
    problems = []
    listed = {"files/" + e["path"]: e for e in m.get("files", []) if not e.get("original_missing")}
    present = {r for r in rests if r != "manifest.json"}
    if present != set(listed):
        problems.append("snapshot_file_list_mismatch")
    for rel, e in listed.items():
        data = blob(base + rel)
        if data is None or sha256(data) != e.get("copy_sha256") or len(data) != e.get("copy_bytes"):
            problems.append("snapshot_blob_mismatch")
            break
    parts = base.rstrip("/").split("/")
    if m.get("snapshot_id") != parts[-1] or m.get("policy_version") != parts[-2] or m.get("session_id") != parts[-3]:
        problems.append("snapshot_path_mismatch")
    elif snapshot_id(m) != parts[-1] or m.get("snapshot_sha256") != snapshot_sha256(m):
        problems.append("snapshot_id_mismatch")
    return problems


def check_changes(changes: list[tuple[str, str]], blob, *, allow_source: bool) -> list[str]:
    """커밋(또는 index) 변경 검사.

    - live·.ai-logging 경로는 언제나 금지.
    - 스냅샷은 추가만 허용(수정·삭제 금지)하고, 추가된 스냅샷 폴더는 완전해야 한다.
    - allow_source=False(로그 전용 커밋)이면 스냅샷 밖 변경이 하나라도 있으면 실패.
    """
    problems = []
    added_logs = []
    for st, path in changes:
        if path.startswith(FORBIDDEN_PREFIXES):
            problems.append("forbidden_path")
        elif is_log_path(path):
            if st != "A":
                problems.append("snapshot_modified_or_deleted")
            else:
                added_logs.append(path)
        elif not allow_source:
            problems.append("non_log_change")
    groups, bad = snapshot_groups(added_logs)
    if bad:
        problems.append("snapshot_path_format")
    for base, rests in sorted(groups.items()):
        problems.extend(check_snapshot_group(base, rests, blob))
    return sorted(set(problems))
"""두 도구의 네이티브 세션 원본 탐색.

판정은 폴더 이름이 아니라 기록 안의 cwd 값으로 한다. Claude 프로젝트 폴더 이름은
'_'를 '-'로 바꿔 만들기 때문에 다른 경로와 겹칠 수 있다.
"""
from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field

from .common import Context, git, is_within, native_path, norm_path

_UUID_RE = re.compile(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")
_REF_KEY_RE = re.compile(r"(parent|fork|source|thread)", re.IGNORECASE)

# cwd를 찾기 위해 한 파일에서 읽는 최대 범위
_MAX_SCAN_LINES = 2000
_MAX_SCAN_BYTES = 8 * 1024 * 1024


@dataclass
class SessionFile:
    rel: str  # 세션 기준 상대 경로(POSIX 구분자). 사본 경로에 그대로 쓴다.
    path: str  # 원본 절대 경로
    role: str  # "main" | "attachment"


@dataclass
class Session:
    tool: str
    session_id: str
    main_path: str
    files: list[SessionFile] = field(default_factory=list)

    @property
    def key(self) -> str:
        return f"{self.tool}/{self.session_id}"


@dataclass
class Discovery:
    sessions: list[Session]
    unresolved: int  # cwd도 부모 연결도 확인하지 못한 Codex 파일 수
    roots: list[str]


def project_roots(ctx: Context, state: dict) -> list[str]:
    roots = [ctx.root]
    out = git(ctx.root, "worktree", "list", "--porcelain")
    if out:
        for line in out.splitlines():
            if line.startswith("worktree "):
                roots.append(line[len("worktree "):].strip())
    roots.extend(state.get("extra_roots", []))
    seen, uniq = set(), []
    for r in roots:
        n = norm_path(r)
        if n not in seen:
            seen.add(n)
            uniq.append(r)
    return uniq


def _in_roots(cwd, roots) -> bool:
    return isinstance(cwd, str) and any(is_within(cwd, r) for r in roots)


def _read_claude_cwd(path: str):
    read = 0
    with open(path, "rb") as f:
        for i, line in enumerate(f):
            read += len(line)
            if i >= _MAX_SCAN_LINES or read > _MAX_SCAN_BYTES:
                break
            try:
                o = json.loads(line)
            except ValueError:
                continue
            if isinstance(o, dict) and isinstance(o.get("cwd"), str):
                return o["cwd"]
    return None


def _collect_refs(obj, depth=0, under_ref_key=False, out=None):
    out = set() if out is None else out
    if depth > 3:
        return out
    if isinstance(obj, dict):
        for k, v in obj.items():
            _collect_refs(v, depth + 1, under_ref_key or bool(_REF_KEY_RE.search(str(k))), out)
    elif isinstance(obj, list):
        for v in obj[:20]:
            _collect_refs(v, depth + 1, under_ref_key, out)
    elif isinstance(obj, str) and under_ref_key:
        out.update(m.group(0).lower() for m in _UUID_RE.finditer(obj))
    return out


def _read_codex_meta(path: str):
    with open(path, "rb") as f:
        first = f.readline()
    try:
        o = json.loads(first)
    except ValueError:
        return None
    if not isinstance(o, dict) or o.get("type") != "session_meta":
        return None
    p = o.get("payload") if isinstance(o.get("payload"), dict) else {}
    sid = p.get("id") or p.get("session_id")
    if not isinstance(sid, str):
        m = _UUID_RE.search(os.path.basename(path))
        sid = m.group(0) if m else None
    refs = sorted(_collect_refs(p) - ({sid.lower()} if sid else set()))
    return {"cwd": p.get("cwd") if isinstance(p.get("cwd"), str) else None, "id": sid, "refs": refs}


def _cached(cache: dict, path: str, loader):
    """경로별 메타데이터 캐시. cwd를 찾은 경우에만 저장한다(새 파일은 다시 읽는다)."""
    hit = cache.get(path)
    if hit is not None:
        return hit
    try:
        value = loader(path)
    except OSError:
        return None
    if value is not None and (not isinstance(value, dict) or value.get("cwd") or value.get("refs")):
        cache[path] = value
    return value


def _is_plain_file(p: str) -> bool:
    return os.path.isfile(p) and not os.path.islink(p)


def discover_claude(ctx: Context, roots: list[str], cache: dict) -> list[Session]:
    base = os.path.join(ctx.claude_home, "projects")
    if not os.path.isdir(base):
        return []
    sessions = []
    for proj in sorted(os.listdir(base)):
        pdir = os.path.join(base, proj)
        if not os.path.isdir(pdir) or os.path.islink(pdir):
            continue
        for name in sorted(os.listdir(pdir)):
            fpath = os.path.join(pdir, name)
            if not name.endswith(".jsonl") or not _is_plain_file(fpath):
                continue
            meta = _cached(cache, fpath, lambda p: {"cwd": _read_claude_cwd(p)})
            if not meta or not _in_roots(meta.get("cwd"), roots):
                continue
            sessions.append(claude_session(fpath))
    return sessions


def claude_session(main_path: str, sid: str | None = None) -> Session:
    """Claude 주 JSONL과 같은 이름 폴더(<sid>/, subagents·tool-results 등)의 전체 파일."""
    pdir, name = os.path.split(main_path)
    sid = sid or name[: -len(".jsonl")]
    s = Session("claude", sid, main_path, [SessionFile(name, main_path, "main")])
    sdir = os.path.join(pdir, name[: -len(".jsonl")])
    if os.path.isdir(sdir) and not os.path.islink(sdir):
        for dirpath, dirnames, filenames in os.walk(sdir, followlinks=False):
            dirnames[:] = sorted(d for d in dirnames if not os.path.islink(os.path.join(dirpath, d)))
            for fn in sorted(filenames):
                fp = os.path.join(dirpath, fn)
                if fn.endswith(".tmp") or ".tmp-" in fn or not _is_plain_file(fp):
                    continue
                rel = os.path.relpath(fp, pdir).replace(os.sep, "/")

"""불변 스냅샷과 로그 전용 커밋.

경로: ai-logs/snapshots/<tool>/<session-id>/<policy-version>/L<원본 바이트 20자리>-<sha256 앞 16자리>/
  manifest.json  + files/<원본 상대 경로>  (세션의 모든 파일 전체 사본, 마스킹만 적용)

- 같은 원본·같은 정책이면 같은 ID(폴더 이름)가 나온다. 생성 시각 같은 가변 값은 manifest에 넣지 않는다.
- 전체 sha256은 manifest의 snapshot_sha256에 기록한다(폴더 이름에는 앞 16자리만).
- 이미 있는 폴더는 고치지 않는다. 같은 ID인데 내용이 다르면 보류한다.
- 원본 길이가 같은데 내용(해시)이 다른 스냅샷은 '더 최신'으로 추정하지 않고 보류한다.
- 원본 앞부분 불변성(절단·재작성·삭제)은 이전 스냅샷·live·상태 기록 모두와 대조한다.
"""
from __future__ import annotations

import json
import os
import hashlib

from .common import (
    LARGE_FILE_BYTES,
    SCHEMA_VERSION,
    SNAPSHOTS_REL,
    Context,
    GitError,
    atomic_write,
    dumps_json,
    file_lock,
    read_json_ro,
    sha256,
    utc_now,
)
from .discover import Session, resolve_targets

TIME_BASIS = "UTC - 도구가 기록한 ISO 8601 timestamp 값을 그대로 사용"
ORDER_BASIS = "파일 안의 줄 순서 (타임스탬프로 재정렬하지 않음)"


# ------------------------------------------------------------------ identity
def _id_payload(m: dict) -> bytes:
    files = sorted(
        [e["path"], e["original_bytes"], e["original_sha256"], e["copy_sha256"]] for e in m.get("files", [])
    )
    payload = {
        "schema": m.get("schema"),
        "tool": m.get("tool"),
        "session_id": m.get("session_id"),
        "policy_version": m.get("policy_version"),
        "files": files,
    }
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def snapshot_sha256(m: dict) -> str:
    return sha256(_id_payload(m))


def snapshot_id(m: dict) -> str:
    """manifest 내용으로 ID를 다시 계산한다(경로를 믿지 않는다)."""
    total = sum(int(e["original_bytes"]) for e in m.get("files", []))
    return "L%020d-%s" % (total, snapshot_sha256(m)[:16])


def snap_base(tool: str, sid: str, policy: str, sid_: str) -> str:
    return f"{SNAPSHOTS_REL}/{tool}/{sid}/{policy}/{sid_}/"


# ------------------------------------------------------------ known snapshots
def worktree_manifests(ctx: Context) -> dict[str, dict]:
    """작업 폴더의 스냅샷 manifest {base 경로: manifest}. 읽을 수 없는 manifest는 base만 표시(None)."""
    out: dict[str, dict] = {}
    root = ctx.snapshots_dir
    if not os.path.isdir(root):
        return out
    for tool in sorted(os.listdir(root)):
        for sid in sorted(_dirs(os.path.join(root, tool))):
            for pol in sorted(_dirs(os.path.join(root, tool, sid))):
                for snap in sorted(_dirs(os.path.join(root, tool, sid, pol))):
                    m, st = read_json_ro(os.path.join(root, tool, sid, pol, snap, "manifest.json"))
                    out[snap_base(tool, sid, pol, snap)] = m if st == "ok" and isinstance(m, dict) else None
    return out


def _dirs(path: str) -> list[str]:
    try:
        return [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d))]
    except OSError:
        return []


def tree_manifests(root: str, treeish: str) -> dict[str, dict]:
    """커밋 트리 안의 스냅샷 manifest {base 경로: manifest}(Git blob에서 읽음)."""
    from . import gitops

    files = gitops.tree_files(root, treeish, SNAPSHOTS_REL)
    mans = {p: oid for p, (_, oid) in files.items() if p.endswith("/manifest.json")}
    blobs = gitops.cat_blobs(root, mans.values())
    out = {}
    for path, oid in mans.items():
        base = path[: -len("manifest.json")]
        try:
            out[base] = json.loads(blobs[oid].decode("utf-8"))
        except (KeyError, ValueError, UnicodeDecodeError):
            out[base] = None
    return out


def known_manifests(ctx: Context, refs=()) -> dict[str, dict]:
    """작업 폴더 + 주어진 커밋들의 스냅샷 manifest 합집합."""
    out = {}
    for ref in refs:
        try:
            out.update({k: v for k, v in tree_manifests(ctx.root, ref).items() if k not in out or out[k] is None})
        except GitError:
            continue
    for k, v in worktree_manifests(ctx).items():
        if k not in out or out[k] is None:
            out[k] = v
    return out


def by_session(manifests: dict[str, dict]) -> dict[str, list[tuple[str, dict]]]:
    out: dict[str, list] = {}
    for base, m in manifests.items():
        parts = base.rstrip("/").split("/")
        out.setdefault(f"{parts[-4]}/{parts[-3]}", []).append((base, m))
    return out


def latest(entries: list[tuple[str, dict]], policy_version: str):
    """정책별 최신 스냅샷: 원본 바이트가 가장 큰 것. 같은 길이에 다른 ID가 있으면 (None, 'ambiguous')."""
    cands = [(b, m) for b, m in entries if m and m.get("policy_version") == policy_version]
    if not cands:
        return None, "none"
    top = max(m.get("original_bytes_total", -1) for _, m in cands)
    tops = {m.get("snapshot_id") for _, m in cands if m.get("original_bytes_total") == top}
    if len(tops) > 1:
        return None, "ambiguous"
    return next((b, m) for b, m in cands if m.get("original_bytes_total") == top), "ok"


# ------------------------------------------------------------------- create
def _prefix_problems(rel: str, data: bytes, prior: list[tuple[int, str]]) -> list[str]:
    out = []
    digest = hashlib.sha256()
    position = 0
    for n, h in sorted(set(prior)):
        if len(data) < n:
            out.append("original_truncated")
        else:
            digest.update(memoryview(data)[position:n])
            position = n
            if digest.hexdigest() != h:
                out.append("original_rewritten")
    return sorted(set(out))


def _prior_knowledge(session_key: str, state: dict, snaps: list[tuple[str, dict]]) -> dict[str, list]:
    """파일별 (원본 바이트, 앞부분 sha256) 기록: 상태(live 수집) + 모든 이전 스냅샷."""
    prior: dict[str, list] = {}
    prefix = session_key + "/"
    for k, v in (state.get("files") or {}).items():
        if k.startswith(prefix) and isinstance(v.get("original_bytes"), int) and v.get("original_sha256"):
            prior.setdefault(k[len(prefix):], []).append((v["original_bytes"], v["original_sha256"]))
    for _, m in snaps:
        for e in (m or {}).get("files", []):
            if isinstance(e.get("original_bytes"), int) and e.get("original_sha256"):
                prior.setdefault(e["path"], []).append((e["original_bytes"], e["original_sha256"]))
    return prior


def build_snapshot(ctx: Context, s: Session, policy, state: dict, snaps: list[tuple[str, dict]],
                   idle: bool) -> dict:
    """세션 하나의 스냅샷을 준비한다(쓰지 않음). 결과: {status: ready|hold, manifest, copies, problems, ...}.

    개행 없는 마지막 JSONL 기록: 세션이 idle로 확인되고 그 꼬리가 JSON으로 파싱되면 '종료된 유효 기록'으로
    포함한다. 그 밖에는 마지막 개행까지만 담고 deferred_tail로 보고한다(최종 완전성 검사는 실패한다).
    """
    from .engine import check_masked, jsonl_stats, read_full

    problems, warnings, deferred = [], [], []
    prior = _prior_knowledge(s.key, state, snaps)
    entries, copies = [], {}
    current = {f.rel for f in s.files}
    for rel in sorted(set(prior) - current):
        problems.append({"rule": "original_file_deleted", "file": rel})
    main_stats = (0, None, None)
    for f in s.files:
        try:
            data = read_full(f)
        except OSError as e:
            problems.append({"rule": "original_unreadable", "file": f.rel, "detail": type(e).__name__})
            continue
        ends_open = False
        if f.rel.endswith(".jsonl") and data and not data.endswith(b"\n"):
            cut = data.rfind(b"\n") + 1
            tail = data[cut:]
            try:
                json.loads(tail)
                tail_ok = True
            except ValueError:
                tail_ok = False
            if idle and tail_ok:
                ends_open = True
            else:
                deferred.append({"file": f.rel, "bytes": len(tail), "reason": "unterminated_tail"})
                data = data[:cut]
        for rule in _prefix_problems(f.rel, data, prior.get(f.rel, [])):
            problems.append({"rule": rule, "file": f.rel})
        masked, counts = policy.mask(data)
        for p in check_masked(f.rel, data, masked, policy):
            problems.append(p)
        if len(data) > LARGE_FILE_BYTES:
            warnings.append({"rule": "large_file", "file": f.rel, "detail": f"bytes={len(data)}"})
        entry = {
            "path": f.rel,
            "role": f.role,
            "original_bytes": len(data),
            "original_sha256": sha256(data),
            "copy_bytes": len(masked),
            "copy_sha256": sha256(masked),
            "masked": dict(sorted(counts.items())),
        }
        if f.rel.endswith(".jsonl"):
            n, first, last, bad = jsonl_stats(data)
            entry["lines"] = n
            entry["ends_without_newline"] = ends_open
            if bad:
                entry["non_json_lines"] = bad[:50]
            if f.role == "main":
                main_stats = (n, first, last)
        entries.append(entry)
        copies[f.rel] = masked
    entries.sort(key=lambda e: (e["role"] != "main", e["path"]))
    n, first, last = main_stats
    m = {
        "schema": SCHEMA_VERSION,
        "kind": "snapshot",
        "tool": s.tool,
        "session_id": s.session_id,
        "policy_version": policy.version,
        "time_basis": TIME_BASIS,
        "order_basis": ORDER_BASIS,
        "first_timestamp": first,
        "last_timestamp": last,
        "main_lines": n,
        "original_bytes_total": sum(e["original_bytes"] for e in entries),
        "files": entries,
        "warnings": warnings,
    }
    m["snapshot_sha256"] = snapshot_sha256(m)
    m["snapshot_id"] = snapshot_id(m)
    # 같은 정책에서 같은 길이·다른 내용, 또는 더 긴 스냅샷이 이미 있는데 지금이 더 짧은 경우
    for base, old in snaps:
        if not old or old.get("policy_version") != policy.version:
            continue
        if old.get("original_bytes_total") == m["original_bytes_total"] and old.get("snapshot_id") != m["snapshot_id"]:
            problems.append({"rule": "same_length_different_snapshot", "detail": base})
    status = "hold" if problems else "ready"
    return {"key": s.key, "status": status, "manifest": m, "copies": copies, "problems": problems,
            "warnings": warnings, "deferred": deferred,
            "base": snap_base(s.tool, s.session_id, policy.version, m["snapshot_id"])}


def write_snapshot(ctx: Context, prep: dict) -> str:
    """준비된 스냅샷을 쓴다. 이미 있으면 내용이 같은지 확인만 한다. 반환: created|exists|conflict."""
    base_abs = os.path.join(ctx.root, *prep["base"].rstrip("/").split("/"))
    mpath = os.path.join(base_abs, "manifest.json")
    want = dumps_json(prep["manifest"])
    if os.path.exists(mpath):
        with open(mpath, "rb") as f:
            have = f.read()
        if have != want:
            return "conflict"
        for rel, data in prep["copies"].items():
            p = os.path.join(base_abs, "files", *rel.split("/"))
            try:
                with open(p, "rb") as f:
                    if f.read() != data:
                        return "conflict"
            except FileNotFoundError:
                return "conflict"
        return "exists"
    for rel, data in prep["copies"].items():
        atomic_write(os.path.join(base_abs, "files", *rel.split("/")), data)
    atomic_write(mpath, want)  # manifest를 마지막에 써서 '완성된 폴더'의 표시로 삼는다
    return "created"


def snapshot_all(ctx: Context, refs=("HEAD",), states: dict | None = None) -> dict:
    """대상 세션 전체 스냅샷. 보류가 하나라도 있으면 그 세션은 쓰지 않는다."""
    from .engine import build_policy, load_state

    with file_lock(ctx.lock_path, timeout=60):
        state = load_state(ctx)
        policy = build_policy(ctx)
        known = known_manifests(ctx, refs)
        grouped = by_session(known)
        targets = resolve_targets(ctx, state, extra_known=grouped.keys())
        report = {"time": utc_now(), "policy_version": policy.version, "sessions": [], "holds": [],
                  "warnings": [], "missing": [], "result": "ok"}
        if not os.path.exists(ctx.mask_path):
            report.update(result="error", error="mask_list_missing")
            return report
        for s in targets.sessions:
            idle = bool(states and states.get(s.key, {}).get("state") == "idle")
            prep = build_snapshot(ctx, s, policy, state, grouped.get(s.key, []), idle)
            row = {"key": s.key, "base": prep["base"], "status": prep["status"],
                   "original_bytes": prep["manifest"]["original_bytes_total"],
                   "main_lines": prep["manifest"]["main_lines"],
                   "last_timestamp": prep["manifest"]["last_timestamp"]}
            if prep["deferred"]:
                row["deferred"] = prep["deferred"]
            if prep["status"] == "ready":
                row["status"] = write_snapshot(ctx, prep)
                if row["status"] == "conflict":
                    report["holds"].append({"rule": "snapshot_dir_conflict", "session": s.key})
            else:
                report["holds"].extend(dict(p, session=s.key) for p in prep["problems"])
            report["warnings"].extend(dict(w, session=s.key) for w in prep["warnings"])
            report["sessions"].append(row)
        for key in targets.missing:
            has = bool(grouped.get(key))
            report["missing"].append({"session": key, "snapshot_kept": has})
        if report["holds"]:
            report["result"] = "hold"
        return report


# ------------------------------------------------------------- completeness
def completeness(ctx: Context, treeish: str | None, policy=None, read_originals: bool = True) -> dict:
    """커밋(또는 작업 폴더) 기준 제출 완전성.

    모든 대상 세션에 대해, 현재 정책의 최신 스냅샷이 원본 파일 전체(EOF)와 같은지 확인한다.
    failures가 비어 있어야 '완전'이다. 원본이 사라진 세션은 이전 스냅샷이 있으면 경고, 없으면 실패.
    """
    from .engine import build_policy, load_state

    policy = policy or build_policy(ctx)
    mans = tree_manifests(ctx.root, treeish) if treeish else worktree_manifests(ctx)
    grouped = by_session(mans)
    state = load_state(ctx)
    targets = resolve_targets(ctx, state, extra_known=grouped.keys())
    failures, warnings, rows = [], [], []
    for base, m in mans.items():
        if m is None:
            failures.append({"rule": "snapshot_manifest_unreadable", "detail": base})
    for s in targets.sessions:
        pick, how = latest(grouped.get(s.key, []), policy.version)
        if pick is None:
            failures.append({"rule": "snapshot_missing" if how == "none" else "snapshot_ambiguous", "session": s.key})
            continue
        b, m = pick
        listed = {e["path"]: e for e in m["files"]}
        cur = {f.rel: f for f in s.files}
        for rel in sorted(set(cur) - set(listed)):
            failures.append({"rule": "file_not_in_snapshot", "session": s.key, "file": rel})
        if read_originals:
            for rel, e in listed.items():
                f = cur.get(rel)
                if f is None:
                    failures.append({"rule": "original_file_deleted", "session": s.key, "file": rel})
                    continue
                try:
                    size = os.path.getsize(f.path)
                    with open(f.path, "rb") as fh:
                        head = fh.read(e["original_bytes"])
                except OSError:
                    failures.append({"rule": "original_unreadable", "session": s.key, "file": rel})
                    continue
                if size < e["original_bytes"] or sha256(head) != e["original_sha256"]:
                    failures.append({"rule": "original_changed", "session": s.key, "file": rel})
                elif size > e["original_bytes"]:
                    failures.append({"rule": "snapshot_behind_original", "session": s.key, "file": rel,
                                     "detail": f"bytes={size - e['original_bytes']}"})
        rows.append({"key": s.key, "snapshot": b, "original_bytes": m.get("original_bytes_total")})
    for key in targets.missing:
        if grouped.get(key):
            warnings.append({"rule": "original_missing_snapshot_kept", "session": key})
        else:
            failures.append({"rule": "original_missing_not_snapshotted", "session": key})
    if targets.unresolved:
        warnings.append({"rule": "unresolved_codex_files", "detail": f"count={targets.unresolved}"})
    return {"treeish": treeish or "worktree", "policy_version": policy.version, "sessions": rows,
            "failures": failures, "warnings": warnings, "complete": not failures}


def scan_tree_secrets(ctx: Context, treeish: str, policy=None) -> list[dict]:
    """커밋 트리의 모든 스냅샷 blob을 현재 정책으로 다시 검사한다(치환 목록 잔류·민감정보 후보).

    이미 커밋된 값은 새 마스킹 커밋으로 지워지지 않는다. 발견되면 게시를 멈추고 보고한다.
    """
    from . import gitops
    from .engine import build_policy

    policy = policy or build_policy(ctx)
    files = gitops.tree_files(ctx.root, treeish, SNAPSHOTS_REL)
    from .progress import report

    paths = {}
    for path, (_, oid) in sorted(files.items()):
        if "/files/" in path:
            paths.setdefault(oid, []).append(path)
    cache = getattr(policy, "cache", None)
    passed = cache.known("git-blob", paths) if cache else set()
    report(f"스냅샷 비밀 검사: 고유 파일 {len(paths)}개, 기존 통과 {len(passed)}개, 검사 대상 {len(paths) - len(passed)}개")
    out = []
    done = len(passed)
    for batch in gitops.blob_batches(ctx.root, set(paths) - passed):
        blobs = gitops.cat_blobs(ctx.root, batch)
        for oid in batch:
            if oid not in blobs:
                issues = [{"rule": "committed_blob_unreadable"}]
            else:
                data = blobs[oid]
                # residue는 줄을 가로지르는 치환도 검사하므로 전체 바이트로 검사한다.
                issues = [{"rule": "committed_mask_residue"}] if policy.residue(data) else []
                issues += [{"rule": "committed_" + h.rule, "line": h.line} for h in policy.detect(data)]
            for path in paths[oid]:
                out.extend(dict(p, file=path) for p in issues)
            if not issues and cache:
                cache.remember("git-blob", [oid])
            done += 1
        report(f"스냅샷 비밀 검사: {done}/{len(paths)}개 확인")
    return sorted(out, key=lambda x: (x["file"], x.get("line", 0), x["rule"]))


# ------------------------------------------------------------ live coverage
def live_covered(ctx: Context) -> dict:
    """live 사본 ⊆ 스냅샷: live 제외 정책으로 바꾸기 전 확인.

    각 live 파일에 대해 같은 세션의 최신 스냅샷(정책 무관, 원본 바이트 최대)이 live보다 길거나 같고,
    현재 원본 기준으로 두 범위가 모두 같은 원본의 앞부분이며, 같은 정책이면 스냅샷 사본이 live 사본으로 시작한다.
    """
    import glob

    snaps = by_session(worktree_manifests(ctx))
    gaps, checked = [], 0
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m, st = read_json_ro(mpath)
        if st != "ok":
            gaps.append({"rule": "live_manifest_unreadable", "detail": os.path.basename(os.path.dirname(mpath))})
            continue
        key = f"{m['tool']}/{m['session_id']}"
        cands = [x for x in snaps.get(key, []) if x[1]]
        for e in m["files"]:
            checked += 1
            best = None
            for base, sm in cands:
                se = next((x for x in sm["files"] if x["path"] == e["path"]), None)
                if se and se["original_bytes"] >= e["original_bytes"]:
                    if best is None or se["original_bytes"] > best[1]["original_bytes"]:
                        best = (base, se, sm)
            if best is None:
                gaps.append({"rule": "live_not_in_snapshot", "session": key, "file": e["path"]})
                continue
            base, se, sm = best
            live_copy = os.path.join(os.path.dirname(mpath), "files", *e["path"].split("/"))
            snap_copy = os.path.join(ctx.root, *base.rstrip("/").split("/"), "files", *e["path"].split("/"))
            if sm.get("policy_version") == m.get("policy_version"):
                with open(live_copy, "rb") as a, open(snap_copy, "rb") as b:
                    if not b.read().startswith(a.read()):
                        gaps.append({"rule": "snapshot_not_extending_live", "session": key, "file": e["path"]})
            # 정책이 다르면 원본 기준으로 대조: live 범위와 스냅샷 범위가 같은 원본의 앞부분이어야 한다
            orig = _original_path(ctx, key, e["path"])
            if orig:
                with open(orig, "rb") as f:
                    data = f.read(se["original_bytes"])
                if sha256(data[: e["original_bytes"]]) != e["original_sha256"] or sha256(data) != se["original_sha256"]:
                    gaps.append({"rule": "live_snapshot_original_mismatch", "session": key, "file": e["path"]})
            elif sm.get("policy_version") != m.get("policy_version"):
                gaps.append({"rule": "original_missing_cannot_compare", "session": key, "file": e["path"]})
    return {"files_checked": checked, "gaps": gaps, "covered": not gaps}


def _original_path(ctx: Context, key: str, rel: str):
    from .engine import load_state

    targets = resolve_targets(ctx, load_state(ctx))
    for s in targets.sessions:
        if s.key == key:
            for f in s.files:
                if f.rel == rel:
                    return f.path
    return None


# ---------------------------------------------------------------- commit
def _message(task: str, title: str, rows: list[dict], policy_version: str, added: list[str],
             held: dict | None = None) -> str:
    body = [f"  스냅샷 {len(added)}개 추가 (정책 {policy_version}, 세션 {len(rows)}개 확인)"]
    for r in rows:
        if r["base"] in added:
            body.append(f"  - {r['key']}: {r['base'].rstrip('/').split('/')[-1]}, {r['main_lines']}줄, "
                        f"마지막 {r['last_timestamp']}")
    for key, n in sorted((held or {}).items()):
        body.append(f"  - {key}: 보류 {n}건으로 이번 커밋 제외 (해소 뒤 다음 스냅샷에 이어서 반영)")
    return f"[{task}] {title}\n\n" + "\n".join(body) + "\n"


def commit_snapshots(ctx: Context, task: str, title: str, *, branch: str | None = None,
                     expect_branch: str | None = None, expect_head: str | None = None, states: dict | None = None,
                     require_complete: bool = False, extra_refs=()) -> dict:
    """브랜치에 로그 전용 커밋(부모 1개)을 만든다. 사용자 index·작업 폴더의 다른 항목은 바꾸지 않는다.

    branch를 주면 체크아웃하지 않은 브랜치에도 ref만 비교 후 교체(CAS)로 커밋한다(작업 폴더 전환 없음).
    중단 조건: 분리된 HEAD, 진행 중인 Git 작업, 스테이징된 변경, 예상과 다른 브랜치·HEAD.
    스냅샷 보류 세션은 중단 사유가 아니다: 그 세션만 빼고 커밋하고 결과의 held에 세션별 건수를 돌려준다.
    변경할 스냅샷이 없으면 커밋하지 않는다(빈 커밋 금지).
    """
    from . import gitops, rules

    root = ctx.root
    current = gitops.current_branch(root)
    target = branch or current
    if not target:
        return {"ok": False, "reason": "detached_head"}
    if expect_branch and current != expect_branch:
        return {"ok": False, "reason": "branch_changed", "detail": f"{expect_branch}->{current}"}
    head = gitops.rev(root, f"refs/heads/{target}")
    if expect_head and head != expect_head:
        return {"ok": False, "reason": "head_changed"}
    busy = gitops.in_progress(root)
    if busy:
        return {"ok": False, "reason": "git_operation_in_progress", "detail": ",".join(busy)}
    if target == current and gitops.staged_changes(root):
        return {"ok": False, "reason": "staged_changes_present"}
    if not rules.TASK_ID_RE.match(task or ""):
        return {"ok": False, "reason": "task_id_format", "detail": "예: SETUP-001"}
    from . import config

    mm = config.check_branch_task(ctx, task, target)
    if mm:
        return {"ok": False, "reason": "task_branch_mismatch", "detail": mm.split(":", 1)[1]}
    refs = tuple(r for r in ((head,) if head else ()) + tuple(extra_refs) if r)
    rep = snapshot_all(ctx, refs=refs, states=states)
    if rep["result"] not in ("ok", "hold"):
        return {"ok": False, "reason": f"snapshot_{rep['result']}", "snapshot": rep}
    # 보류(민감정보 후보·원본 이상) 세션은 이번 커밋에서 통째로 뺀다. 값은 게시되지 않는다.
    # 나머지 세션은 그대로 커밋한다. 보류 세션은 해소 뒤 다음 스냅샷(전체본)에 순서대로 이어서 쌓인다.
    held: dict[str, int] = {}
    for h in rep["holds"]:
        held[h["session"]] = held.get(h["session"], 0) + 1
    in_head = tree_manifests(root, head) if head else {}
    wt = worktree_manifests(ctx)
    current_bases = {r["base"] for r in rep["sessions"]}
    # 이번 실행의 최신 스냅샷 + 이전 실행에서 커밋하지 못한 온전한 폴더(같은 정책)를 함께 올린다.
    added = sorted(b for b, m in wt.items() if m is not None and b not in in_head
                   and f"{m.get('tool')}/{m.get('session_id')}" not in held
                   and (b in current_bases or m.get("policy_version") == rep["policy_version"]))
    if require_complete:
        comp = completeness(ctx, None)
        if not comp["complete"]:
            return {"ok": False, "reason": "not_complete", "completeness": comp}
    if not added:
        return {"ok": True, "committed": False, "reason": "nothing_to_commit", "commit": head, "snapshot": rep,
                "held": held}
    paths = []
    for b in added:
        base_abs = os.path.join(root, *b.rstrip("/").split("/"))
        for dirpath, _, fns in os.walk(base_abs):
            for fn in fns:
                paths.append(os.path.relpath(os.path.join(dirpath, fn), root).replace(os.sep, "/"))
    oids = gitops.hash_files(root, sorted(paths))
    msg = _message(task, title, rep["sessions"], rep["policy_version"], added, held)
    problems = rules.check_message(msg)
    if problems:
        return {"ok": False, "reason": "message_format", "detail": ",".join(problems)}
    commit, _ = gitops.build_commit(root, head, msg, add={p: ("100644", o) for p, o in oids.items()},
                                    state_dir=ctx.state_dir)
    changes = gitops.diff_tree(root, head, commit)
    files = gitops.tree_files(root, commit, SNAPSHOTS_REL)
    blob_cache = {}

    def blob(path):
        if path not in files:
            return None
        oid = files[path][1]
        if oid not in blob_cache:
            blob_cache.update(gitops.cat_blobs(root, [oid]))
        return blob_cache.get(oid)

    problems = rules.check_changes(changes, blob, allow_source=False)
    if problems:
        return {"ok": False, "reason": "log_commit_check_failed", "detail": ",".join(problems)}
    try:
        gitops.cas_update_branch(root, target, commit, head, "log snapshot commit")
    except GitError:
        return {"ok": False, "reason": "head_changed_during_commit"}
    if target == current:
        gitops.sync_index_paths(root, commit, sorted(paths))
    out = {"ok": True, "committed": True, "commit": commit, "branch": target, "snapshots": len(added),
           "sessions": len(rep["sessions"]), "files": len(paths), "missing": rep["missing"], "held": held}
    if held:
        out["snapshot"] = rep  # 보류 형태(값 없음)를 출력하기 위해
    return out


def submit_snapshots(ctx: Context, task: str | None = None, title: str = "세션 로그 제출") -> dict:
    """사용자가 모든 AI 응답이 끝난 뒤 실행하는 제출: 턴 보호 확인 → 전체 스냅샷 → 로그 전용 커밋."""
    from . import config, turns

    task = task or config.task_for_branch(ctx)
    if not task:
        return {"ok": False, "reason": "task_id_required", "detail": "feature 브랜치가 아니면 작업 ID를 지정"}
    with turns.guard_lock(ctx, timeout=20):
        states = turns.effective_states(ctx)
        busy = {k: v["state"] for k, v in states.items() if v["state"] != "idle"}
        if busy:
            return {"ok": False, "reason": "ai_turn_not_idle", "sessions": busy}
        return commit_snapshots(ctx, task, title, states=states)

